process PLINK_LD {
    tag "$meta.id"
    label 'process_low'

    conda "${moduleDir}/environment.yml"
    container "${ workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
?         'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/59/5901c2e9a6b11094536c8b0ab0932bd61bb55dbfe9ad270d3babc8f7246a4759/data'
:         'community.wave.seqera.io/library/plink:1.90b6.21--0baa44af6db8f28d' }"

    input:
    tuple val(meta), path(bed),  path(bim), path(fam)
    tuple val(meta2), path(vcf)
    tuple val(meta3), path(bcf)
    tuple val(meta4), path(snpfile)

    output:
    tuple val(meta), path("*.ld")   , emit: ld
    tuple val(meta), path("*.log")  , emit: log
    tuple val(meta), path("*.nosex"), emit: nosex, optional:true
    tuple val("${task.process}"), val('plink'), eval("plink --version 2>&1 | sed 's/^PLINK v//;s/ .*//'"), emit: versions_plink, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def args = task.ext.args ?: ''
    def args2 = task.ext.args2 ?: ''
    def prefix = ""
    // define input string based on provided input files
    // in hierarchical order
    def input_command = ""
    if (bed){
        input_command = "--bed ${bed} --bim ${bim} --fam ${fam}"
        prefix = task.ext.prefix ?: "${meta.id}"
    } else if (vcf) {
        input_command = "--vcf ${vcf}"
        prefix = task.ext.prefix ?: "${meta2.id}"
        meta = meta2
    } else if (bcf) {
        input_command = "--bcf ${bcf}"
        prefix = task.ext.prefix ?: "${meta3.id}"
        meta = meta3
    } else {
        log.error 'ERROR: the input should be either plink native binary format, VCF or BCF'
    }

    """
    plink \\
        $input_command \\
        --threads $task.cpus \\
        $args \\
        $snpfile \\
        --r2 $args2 \\
        --out $prefix
    """


    stub:
    def prefix = ""
    // define input string based on provided input files
    // in hierarchical order
    def input_command = ""
    if (bed){
        input_command = "--bed ${bed} --bim ${bim} --fam ${fam}"
        prefix = task.ext.prefix ?: "${meta.id}"
    } else if (vcf) {
        input_command = "--vcf ${vcf}"
        prefix = task.ext.prefix ?: "${meta2.id}"
        meta = meta2
    } else if (bcf) {
        input_command = "--bcf ${bcf}"
        prefix = task.ext.prefix ?: "${meta3.id}"
        meta = meta3
    } else {
        log.error 'ERROR: the input should be either plink native binary format, VCF or BCF'
    }
    """
    touch ${prefix}.ld
    touch ${prefix}.log
    touch ${prefix}.nosex
    """
}

nextflow_process {

    name "Test Process PLINK_LD"
    script "../main.nf"
    process "PLINK_LD"
    config "./nextflow.config"
    tag "modules"
    tag "modules_nfcore"
    tag "plink"
    tag "plink/ld"

    test("plink - VCF") {

        when {
            params {
                outdir = "test"
            }
            process {
                """
                input[0] = [ [id:"null"], [], [], []]
                input[1] = [
                    [id:"test"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.vcf.gz', checkIfExists: true)
                    ]
                input[2] = [ [id:"null"], []]
                input[3] = [
                    [id:"test"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_random_selected_snp.txt', checkIfExists: true)
                    ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert process.out.log.get(0).get(1) ==~ ".*/*.log" },
                { assert snapshot(
                    process.out.ld,
                    process.out.nosex,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }
    }

    test("plink - binary") {

        when {
            params {
                outdir = "test"
            }
            process {
                """
                input[0] = [
                    [id:"test"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.bed', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.bim', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.fam', checkIfExists: true)
                    ]
                input[1] = [ [id:"null"], []]
                input[2] = [ [id:"null"], []]
                input[3] = [
                    [id:"test"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_random_selected_snp.txt', checkIfExists: true)
                    ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert process.out.log.get(0).get(1) ==~ ".*/*.log" },
                { assert snapshot(
                    process.out.ld,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }
    }

    test("plink - BCF") {

        when {
            params {
                outdir = "test"
            }
            process {
                """
                input[0] = [ [id:"null"], [], [], []]
                input[1] = [ [id:"null"], []]
                input[2] = [
                    [id:"test"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_simulated.bcf.gz', checkIfExists: true)
                    ]
                input[3] = [
                    [id:"test"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/plink_random_selected_snp.txt', checkIfExists: true)
                    ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert process.out.log.get(0).get(1) ==~ ".*/*.log" },
                { assert snapshot(
                    process.out.ld,
                    process.out.nosex,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }
    }
}
